}

.hero {
  padding: 80px 8%;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  background: linear-gradient(90deg, rgba(16, 40, 61, 0.92), rgba(16, 40, 61, 0.65)), url('business.jpg') center/cover no-repeat;
  color: #fff;
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3rem);
